package com.asmj.marketplace.product.service;
import com.asmj.marketplace.category.repository.CategoryRepository;import com.asmj.marketplace.product.model.*;import com.asmj.marketplace.product.repository.*;import com.asmj.marketplace.vendor.repository.VendorRepository;import com.asmj.marketplace.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;import java.time.*;import java.util.*;
@Component @RequiredArgsConstructor public class ProductDataSeeder implements CommandLineRunner{
 final ProductRepository products;final CouponRepository coupons;final VendorRepository vendors;final CategoryRepository categories;final UserRepository users;@Value("${app.seed.enabled:true}") boolean enabled;
 public void run(String...x){if(!enabled||products.count()>0)return;var v=users.findByEmailIgnoreCase("demo.products@asmj.co.in").flatMap(u->vendors.findByUserId(u.getId())).orElse(null);if(v==null)return;var cat=categories.findAll().stream().filter(c->"Products".equalsIgnoreCase(c.getName())).findFirst().orElse(null);String cid=cat==null?null:cat.getId();Instant n=Instant.now();save(v.getId(),cid,"ASMJ-KB-001","Wireless Keyboard","Compact wireless keyboard with multi-device support",1299,1599,"Logitech",List.of("https://placehold.co/800x600/png?text=Keyboard"),n,List.of(variant("Black","ASMJ-KB-001-B",1299,1599,25,5,"black"),variant("White","ASMJ-KB-001-W",1399,1699,12,5,"white")));save(v.getId(),cid,"ASMJ-MS-001","Wireless Mouse","Ergonomic wireless mouse for office and home",699,999,"ASMS",List.of("https://placehold.co/800x600/png?text=Mouse"),n,List.of(variant("Standard","ASMJ-MS-001",699,999,40,8,"standard")));save(v.getId(),cid,"ASMJ-BAG-001","Laptop Backpack","Water-resistant 15.6 inch laptop backpack",1499,1999,"ASMJ Gear",List.of("https://placehold.co/800x600/png?text=Backpack"),n,List.of(variant("15.6 inch","ASMJ-BAG-001",1499,1999,18,5,"15.6")));save(v.getId(),cid,"ASMJ-MUG-001","Insulated Travel Mug","Stainless steel insulated travel mug",899,1199,"ASMJ Home",List.of("https://placehold.co/800x600/png?text=Travel+Mug"),n,List.of(variant("450ml","ASMJ-MUG-001",899,1199,30,6,"450ml")));save(v.getId(),cid,"ASMJ-LAMP-001","LED Desk Lamp","Dimmable desk lamp with USB charging port",1799,2299,"ASMJ Home",List.of("https://placehold.co/800x600/png?text=Desk+Lamp"),n,List.of(variant("White","ASMJ-LAMP-001-W",1799,2299,15,4,"white"),variant("Black","ASMJ-LAMP-001-B",1899,2399,9,3,"black")));save(v.getId(),cid,"ASMJ-PEN-001","Premium Pen Set","Professional writing set for office and students",499,699,"ASMJ Stationery",List.of("https://placehold.co/800x600/png?text=Pen+Set"),n,List.of(variant("Blue","ASMJ-PEN-001-B",499,699,50,10,"blue")));if(coupons.count()==0)coupons.save(Coupon.builder().code("WELCOME10").name("Welcome 10% off").type("PERCENTAGE").value(10).minOrder(500).maxDiscount(300).usageLimit(1000).usedCount(0).active(true).validFrom(n.minusSeconds(3600)).validTo(n.plus(Duration.ofDays(365))).build());}
 void save(String vid,String cid,String sku,String name,String desc,double price,double mrp,String brand,List<String> imgs,Instant n,List<Product.Variant> vs){products.save(Product.builder().vendorId(vid).categoryId(cid).sku(sku).name(name).description(desc).brand(brand).unit("piece").price(price).mrp(mrp).taxRate(5).images(imgs).variants(vs).active(true).approved(true).featured(true).createdAt(n).updatedAt(n).build());}
 Product.Variant variant(String name,String sku,double p,double mrp,int stock,int low,String value){return Product.Variant.builder().id(UUID.randomUUID().toString()).name(name).sku(sku).price(p).mrp(mrp).stock(stock).lowStockThreshold(low).active(true).attributes(Map.of("option",value)).build();}
 }
